SELECT e.name,NOT EXISTS(SELECT 1 FROM aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) a WHERE a.grantee=0 OR a.is_grantable AND a.grantee<>c.relowner) AS public_and_grant_options_absent,NOT EXISTS(SELECT 1 FROM pg_attribute a WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped AND a.attacl IS NOT NULL) AS separate_column_grants_absent FROM (VALUES ('training_sessions'),('training_session_records'),('training_block_results'),('training_exercise_results'),('training_set_results'),('performance_result_corrections'),('coach_athlete_relationships'),('profiles')) e(name) JOIN pg_class c ON c.relnamespace='public'::regnamespace AND c.relname=e.name ORDER BY e.name;
